import{_ as t,o as a,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const d=JSON.parse('{"title":"uORB Message Reference","description":"","frontmatter":{},"headers":[],"relativePath":"ko/msg_docs/index.md","filePath":"ko/msg_docs/index.md"}'),r={name:"ko/msg_docs/index.md"};function l(s,e,n,h,u,f){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="uorb-message-reference" tabindex="-1">uORB Message Reference <a class="header-anchor" href="#uorb-message-reference" aria-label="Permalink to &quot;uORB Message Reference&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This list is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/msg/generate_msg_docs.py" target="_blank" rel="noreferrer">auto-generated</a> from the source code.</p></div><p>This topic lists the UORB messages available in PX4 (some of which may be may be shared by the <a href="./../ros/ros2_comm">PX4-ROS 2 Bridge</a>).</p><p><a href="./../middleware/uorb#message-versioning">Versioned messages</a> track changes to their definitions, with each modification resulting in a version increment. These messages are most likely shared through the PX4-ROS 2 Bridge.</p><p>Graphs showing how these are used <a href="./../middleware/uorb_graph">can be found here</a>.</p><h2 id="versioned-messages" tabindex="-1">Versioned Messages <a class="header-anchor" href="#versioned-messages" aria-label="Permalink to &quot;Versioned Messages&quot;">​</a></h2><h3 id="current-versions" tabindex="-1">Current Versions <a class="header-anchor" href="#current-versions" aria-label="Permalink to &quot;Current Versions&quot;">​</a></h3><ul><li><a href="./ActuatorMotors">ActuatorMotors</a> — Motor control message.</li><li><a href="./ActuatorServos">ActuatorServos</a> — Servo control message.</li><li><a href="./AirspeedValidated">AirspeedValidated</a> — Validated airspeed.</li><li><a href="./ArmingCheckReply">ArmingCheckReply</a> — Arming check reply.</li><li><a href="./ArmingCheckRequest">ArmingCheckRequest</a> — Arming check request.</li><li><a href="./AuxGlobalPosition">AuxGlobalPosition</a> — Auxiliary global position.</li><li><a href="./BatteryStatus">BatteryStatus</a> — Battery status.</li><li><a href="./ConfigOverrides">ConfigOverrides</a> — Configurable overrides by (external) modes or mode executors.</li><li><a href="./Event">Event</a> — Events interface.</li><li><a href="./FixedWingLateralSetpoint">FixedWingLateralSetpoint</a> — Fixed Wing Lateral Setpoint message.</li><li><a href="./FixedWingLongitudinalSetpoint">FixedWingLongitudinalSetpoint</a> — Fixed Wing Longitudinal Setpoint message.</li><li><a href="./GotoSetpoint">GotoSetpoint</a> — Position and (optional) heading setpoints with corresponding speed constraints.</li><li><a href="./HomePosition">HomePosition</a> — GPS home position in WGS84 coordinates.</li><li><a href="./LateralControlConfiguration">LateralControlConfiguration</a> — Fixed Wing Lateral Control Configuration message.</li><li><a href="./LongitudinalControlConfiguration">LongitudinalControlConfiguration</a> — Fixed Wing Longitudinal Control Configuration message.</li><li><a href="./ManualControlSetpoint">ManualControlSetpoint</a></li><li><a href="./ModeCompleted">ModeCompleted</a> — Mode completion result, published by an active mode. The possible values of nav_state are defined in the VehicleStatus msg. Note that this is not always published (e.g. when a user switches modes or on. failsafe activation).</li><li><a href="./RaptorInput">RaptorInput</a> — Raptor Input.</li><li><a href="./RaptorStatus">RaptorStatus</a> — Raptor Status.</li><li><a href="./RegisterExtComponentReply">RegisterExtComponentReply</a></li><li><a href="./RegisterExtComponentRequest">RegisterExtComponentRequest</a> — Request to register an external component.</li><li><a href="./SetpointConfig">SetpointConfig</a> — Setpoint configuration message.</li><li><a href="./SetpointConfigReply">SetpointConfigReply</a> — Reply to SetpointConfig.</li><li><a href="./TrajectorySetpoint">TrajectorySetpoint</a> — Trajectory setpoint in NED frame. Input to PID position controller. Needs to be kinematically consistent and feasible for smooth flight. setting a value to NaN means the state should not be controlled.</li><li><a href="./UnregisterExtComponent">UnregisterExtComponent</a></li><li><a href="./VehicleAngularVelocity">VehicleAngularVelocity</a></li><li><a href="./VehicleAttitude">VehicleAttitude</a> — This is similar to the mavlink message ATTITUDE_QUATERNION, but for onboard use. The quaternion uses the Hamilton convention, and the order is q(w, x, y, z).</li><li><a href="./VehicleAttitudeSetpoint">VehicleAttitudeSetpoint</a></li><li><a href="./VehicleCommand">VehicleCommand</a> — Vehicle Command uORB message. Used for commanding a mission / action / etc. Follows the MAVLink COMMAND_INT / COMMAND_LONG definition.</li><li><a href="./VehicleCommandAck">VehicleCommandAck</a> — Vehicle Command Acknowledgement uORB message.</li><li><a href="./VehicleGlobalPosition">VehicleGlobalPosition</a> — Fused global position in WGS84. This struct contains global position estimation. It is not the raw GPS. measurement (@see vehicle_gps_position). This topic is usually published by the position. estimator, which will take more sources of information into account than just GPS,. e.g. control inputs of the vehicle in a Kalman-filter implementation.</li><li><a href="./VehicleLandDetected">VehicleLandDetected</a></li><li><a href="./VehicleLocalPosition">VehicleLocalPosition</a> — Fused local position in NED. The coordinate system origin is the vehicle position at the time when the EKF2-module was started.</li><li><a href="./VehicleOdometry">VehicleOdometry</a> — Vehicle odometry data.</li><li><a href="./VehicleRatesSetpoint">VehicleRatesSetpoint</a></li><li><a href="./VehicleStatus">VehicleStatus</a> — Encodes the system state of the vehicle published by commander.</li><li><a href="./VtolVehicleStatus">VtolVehicleStatus</a> — VEHICLE_VTOL_STATE, should match 1:1 MAVLinks&#39;s MAV_VTOL_STATE.</li><li><a href="./Wind">Wind</a> — Wind estimate (from EKF2).</li></ul><h3 id="historic-versions" tabindex="-1">Historic Versions <a class="header-anchor" href="#historic-versions" aria-label="Permalink to &quot;Historic Versions&quot;">​</a></h3><ul><li><a href="./ActuatorServosV0">ActuatorServosV0</a> — Servo control message.</li><li><a href="./AirspeedValidatedV0">AirspeedValidatedV0</a></li><li><a href="./ArmingCheckReplyV0">ArmingCheckReplyV0</a></li><li><a href="./ArmingCheckRequestV0">ArmingCheckRequestV0</a> — Arming check request.</li><li><a href="./BatteryStatusV0">BatteryStatusV0</a> — Battery status.</li><li><a href="./ConfigOverridesV0">ConfigOverridesV0</a> — Configurable overrides by (external) modes or mode executors.</li><li><a href="./EventV0">EventV0</a> — this message is required here in the msg_old folder because other msg are depending on it. Events interface.</li><li><a href="./HomePositionV0">HomePositionV0</a> — GPS home position in WGS84 coordinates.</li><li><a href="./HomePositionV1">HomePositionV1</a> — GPS home position in WGS84 coordinates.</li><li><a href="./RegisterExtComponentReplyV0">RegisterExtComponentReplyV0</a></li><li><a href="./RegisterExtComponentRequestV0">RegisterExtComponentRequestV0</a> — Request to register an external component.</li><li><a href="./RegisterExtComponentRequestV1">RegisterExtComponentRequestV1</a> — Request to register an external component.</li><li><a href="./VehicleAttitudeSetpointV0">VehicleAttitudeSetpointV0</a></li><li><a href="./VehicleCommandAckV0">VehicleCommandAckV0</a> — Vehicle Command Ackonwledgement uORB message. Used for acknowledging the vehicle command being received. Follows the MAVLink COMMAND_ACK message definition.</li><li><a href="./VehicleGlobalPositionV0">VehicleGlobalPositionV0</a> — Fused global position in WGS84. This struct contains global position estimation. It is not the raw GPS. measurement (@see vehicle_gps_position). This topic is usually published by the position. estimator, which will take more sources of information into account than just GPS,. e.g. control inputs of the vehicle in a Kalman-filter implementation.</li><li><a href="./VehicleLocalPositionV0">VehicleLocalPositionV0</a> — Fused local position in NED. The coordinate system origin is the vehicle position at the time when the EKF2-module was started.</li><li><a href="./VehicleStatusV0">VehicleStatusV0</a> — Encodes the system state of the vehicle published by commander.</li><li><a href="./VehicleStatusV1">VehicleStatusV1</a> — Encodes the system state of the vehicle published by commander.</li><li><a href="./VehicleStatusV2">VehicleStatusV2</a> — Encodes the system state of the vehicle published by commander.</li><li><a href="./VehicleStatusV3">VehicleStatusV3</a> — Encodes the system state of the vehicle published by commander.</li></ul><h2 id="unversioned-messages" tabindex="-1">Unversioned Messages <a class="header-anchor" href="#unversioned-messages" aria-label="Permalink to &quot;Unversioned Messages&quot;">​</a></h2><ul><li><a href="./ActionRequest">ActionRequest</a> — Action request for the vehicle&#39;s main state.</li><li><a href="./ActuatorArmed">ActuatorArmed</a></li><li><a href="./ActuatorControlsStatus">ActuatorControlsStatus</a></li><li><a href="./ActuatorOutputs">ActuatorOutputs</a></li><li><a href="./ActuatorServosTrim">ActuatorServosTrim</a> — Servo trims, added as offset to servo outputs.</li><li><a href="./ActuatorTest">ActuatorTest</a></li><li><a href="./AdcReport">AdcReport</a> — ADC raw data.</li><li><a href="./Airspeed">Airspeed</a> — Airspeed data from sensors.</li><li><a href="./AirspeedWind">AirspeedWind</a> — Wind estimate (from airspeed_selector).</li><li><a href="./AutotuneAttitudeControlStatus">AutotuneAttitudeControlStatus</a> — Autotune attitude control status.</li><li><a href="./BatteryInfo">BatteryInfo</a> — Battery information.</li><li><a href="./ButtonEvent">ButtonEvent</a></li><li><a href="./CameraCapture">CameraCapture</a></li><li><a href="./CameraStatus">CameraStatus</a></li><li><a href="./CameraTrigger">CameraTrigger</a></li><li><a href="./CanInterfaceStatus">CanInterfaceStatus</a></li><li><a href="./CellularStatus">CellularStatus</a> — Cellular status.</li><li><a href="./CollisionConstraints">CollisionConstraints</a> — Local setpoint constraints in NED frame. setting something to NaN means that no limit is provided.</li><li><a href="./ControlAllocatorStatus">ControlAllocatorStatus</a></li><li><a href="./Cpuload">Cpuload</a></li><li><a href="./DatamanRequest">DatamanRequest</a></li><li><a href="./DatamanResponse">DatamanResponse</a></li><li><a href="./DebugArray">DebugArray</a></li><li><a href="./DebugKeyValue">DebugKeyValue</a></li><li><a href="./DebugValue">DebugValue</a></li><li><a href="./DebugVect">DebugVect</a></li><li><a href="./DetectAndAvoid">DetectAndAvoid</a> — Detect-and-avoid conflict assessment for one traffic aircraft.</li><li><a href="./DetectAndAvoidMostUrgent">DetectAndAvoidMostUrgent</a> — Detect-and-avoid summary for the most urgent active conflict.</li><li><a href="./DeviceInformation">DeviceInformation</a> — Device information.</li><li><a href="./DifferentialPressure">DifferentialPressure</a> — Differential-pressure (airspeed) sensor.</li><li><a href="./DistanceSensor">DistanceSensor</a> — DISTANCE_SENSOR message data.</li><li><a href="./DistanceSensorModeChangeRequest">DistanceSensorModeChangeRequest</a></li><li><a href="./DronecanNodeStatus">DronecanNodeStatus</a></li><li><a href="./Ekf2Timestamps">Ekf2Timestamps</a> — this message contains the (relative) timestamps of the sensor inputs used by EKF2. It can be used for reproducible replay.</li><li><a href="./EscEepromRead">EscEepromRead</a></li><li><a href="./EscEepromWrite">EscEepromWrite</a></li><li><a href="./EscReport">EscReport</a></li><li><a href="./EscStatus">EscStatus</a></li><li><a href="./EstimatorAidSource1d">EstimatorAidSource1d</a></li><li><a href="./EstimatorAidSource2d">EstimatorAidSource2d</a></li><li><a href="./EstimatorAidSource3d">EstimatorAidSource3d</a></li><li><a href="./EstimatorBias">EstimatorBias</a></li><li><a href="./EstimatorBias3d">EstimatorBias3d</a></li><li><a href="./EstimatorEventFlags">EstimatorEventFlags</a></li><li><a href="./EstimatorFusionControl">EstimatorFusionControl</a></li><li><a href="./EstimatorGpsStatus">EstimatorGpsStatus</a></li><li><a href="./EstimatorInnovations">EstimatorInnovations</a></li><li><a href="./EstimatorSelectorStatus">EstimatorSelectorStatus</a></li><li><a href="./EstimatorSensorBias">EstimatorSensorBias</a> — Sensor readings and in-run biases in SI-unit form. Sensor readings are compensated for static offsets,. scale errors, in-run bias and thermal drift (if thermal compensation is enabled and available).</li><li><a href="./EstimatorStates">EstimatorStates</a></li><li><a href="./EstimatorStatus">EstimatorStatus</a></li><li><a href="./EstimatorStatusFlags">EstimatorStatusFlags</a></li><li><a href="./FailsafeFlags">FailsafeFlags</a> — Input flags for the failsafe state machine set by the arming &amp; health checks.</li><li><a href="./FailureDetectorStatus">FailureDetectorStatus</a></li><li><a href="./FailureInjection">FailureInjection</a> — Failure injection configuration.</li><li><a href="./FiducialMarkerPosReport">FiducialMarkerPosReport</a> — Relative position of a precision-landing target detected by a vision pipeline (e.g. an ArUco marker).</li><li><a href="./FiducialMarkerYawReport">FiducialMarkerYawReport</a> — Yaw of a precision-landing target relative to the NED (North, East, Down) frame, reported by a vision pipeline.</li><li><a href="./FigureEightStatus">FigureEightStatus</a></li><li><a href="./FixedWingLateralGuidanceStatus">FixedWingLateralGuidanceStatus</a> — Fixed Wing Lateral Guidance Status message. Published by fw_pos_control module to report the resultant lateral setpoints and NPFG debug outputs.</li><li><a href="./FixedWingLateralStatus">FixedWingLateralStatus</a> — Fixed Wing Lateral Status message. Published by the fw_lateral_longitudinal_control module to report the resultant lateral setpoint.</li><li><a href="./FixedWingRunwayControl">FixedWingRunwayControl</a> — Auxiliary control fields for fixed-wing runway takeoff/landing.</li><li><a href="./FixedWingTakeoffStatus">FixedWingTakeoffStatus</a> — Status of a fixed-wing takeoff. Passes information from the FixedWingModeManager to the Navigator.</li><li><a href="./FlightPhaseEstimation">FlightPhaseEstimation</a></li><li><a href="./FollowTarget">FollowTarget</a></li><li><a href="./FollowTargetEstimator">FollowTargetEstimator</a></li><li><a href="./FollowTargetStatus">FollowTargetStatus</a></li><li><a href="./FuelTankStatus">FuelTankStatus</a></li><li><a href="./GainCompression">GainCompression</a></li><li><a href="./GeneratorStatus">GeneratorStatus</a></li><li><a href="./GeofenceResult">GeofenceResult</a></li><li><a href="./GeofenceStatus">GeofenceStatus</a></li><li><a href="./GimbalControls">GimbalControls</a></li><li><a href="./GimbalDeviceAttitudeStatus">GimbalDeviceAttitudeStatus</a></li><li><a href="./GimbalDeviceInformation">GimbalDeviceInformation</a></li><li><a href="./GimbalDeviceSetAttitude">GimbalDeviceSetAttitude</a></li><li><a href="./GimbalManagerInformation">GimbalManagerInformation</a></li><li><a href="./GimbalManagerSetAttitude">GimbalManagerSetAttitude</a></li><li><a href="./GimbalManagerSetManualControl">GimbalManagerSetManualControl</a></li><li><a href="./GimbalManagerStatus">GimbalManagerStatus</a></li><li><a href="./GpioConfig">GpioConfig</a> — GPIO configuration.</li><li><a href="./GpioIn">GpioIn</a> — GPIO mask and state.</li><li><a href="./GpioOut">GpioOut</a> — GPIO mask and state.</li><li><a href="./GpioRequest">GpioRequest</a> — Request GPIO mask to be read.</li><li><a href="./GpsDump">GpsDump</a> — This message is used to dump the raw gps communication to the log.</li><li><a href="./Gripper">Gripper</a> — # Used to command an actuation in the gripper, which is mapped to a specific output in the control allocation module.</li><li><a href="./HealthReport">HealthReport</a></li><li><a href="./HeaterStatus">HeaterStatus</a></li><li><a href="./HoverThrustEstimate">HoverThrustEstimate</a></li><li><a href="./InputRc">InputRc</a></li><li><a href="./InternalCombustionEngineControl">InternalCombustionEngineControl</a></li><li><a href="./InternalCombustionEngineStatus">InternalCombustionEngineStatus</a></li><li><a href="./IridiumsbdStatus">IridiumsbdStatus</a></li><li><a href="./IrlockReport">IrlockReport</a> — IRLOCK_REPORT message data.</li><li><a href="./LandingGear">LandingGear</a></li><li><a href="./LandingGearWheel">LandingGearWheel</a></li><li><a href="./LandingTargetInnovations">LandingTargetInnovations</a></li><li><a href="./LandingTargetPose">LandingTargetPose</a> — Relative position of precision land target in navigation (body fixed, north aligned, NED) and inertial (world fixed, north aligned, NED) frames.</li><li><a href="./LaunchDetectionStatus">LaunchDetectionStatus</a> — Status of the launch detection state machine (fixed-wing only).</li><li><a href="./LedControl">LedControl</a> — LED control: control a single or multiple LED&#39;s. These are the externally visible LED&#39;s, not the board LED&#39;s.</li><li><a href="./LogMessage">LogMessage</a> — A logging message, output with PX4_WARN, PX4_ERR, PX4_INFO.</li><li><a href="./LoggerStatus">LoggerStatus</a></li><li><a href="./MagWorkerData">MagWorkerData</a></li><li><a href="./MagnetometerBiasEstimate">MagnetometerBiasEstimate</a></li><li><a href="./ManualControlSwitches">ManualControlSwitches</a></li><li><a href="./MavlinkLog">MavlinkLog</a></li><li><a href="./MavlinkTunnel">MavlinkTunnel</a> — MAV_TUNNEL_PAYLOAD_TYPE enum.</li><li><a href="./MessageFormatRequest">MessageFormatRequest</a></li><li><a href="./MessageFormatResponse">MessageFormatResponse</a></li><li><a href="./Mission">Mission</a></li><li><a href="./MissionResult">MissionResult</a></li><li><a href="./MountOrientation">MountOrientation</a></li><li><a href="./NavigatorMissionItem">NavigatorMissionItem</a></li><li><a href="./NavigatorStatus">NavigatorStatus</a> — Current status of a Navigator mode. The possible values of nav_state are defined in the VehicleStatus msg.</li><li><a href="./NeuralControl">NeuralControl</a> — Neural control.</li><li><a href="./NfsUp">NfsUp</a></li><li><a href="./NormalizedUnsignedSetpoint">NormalizedUnsignedSetpoint</a></li><li><a href="./ObstacleDistance">ObstacleDistance</a> — Obstacle distances in front of the sensor.</li><li><a href="./OffboardControlMode">OffboardControlMode</a> — Off-board control mode.</li><li><a href="./OnboardComputerStatus">OnboardComputerStatus</a> — ONBOARD_COMPUTER_STATUS message data.</li><li><a href="./OpenDroneIdArmStatus">OpenDroneIdArmStatus</a></li><li><a href="./OpenDroneIdBasicId">OpenDroneIdBasicId</a></li><li><a href="./OpenDroneIdOperatorId">OpenDroneIdOperatorId</a></li><li><a href="./OpenDroneIdSelfId">OpenDroneIdSelfId</a></li><li><a href="./OpenDroneIdSystem">OpenDroneIdSystem</a></li><li><a href="./OrbTest">OrbTest</a></li><li><a href="./OrbTestLarge">OrbTestLarge</a></li><li><a href="./OrbTestMedium">OrbTestMedium</a></li><li><a href="./OrbitStatus">OrbitStatus</a> — Orbit status.</li><li><a href="./ParameterResetRequest">ParameterResetRequest</a> — ParameterResetRequest : Used by the primary to reset one or all parameter value(s) on the remote.</li><li><a href="./ParameterSetUsedRequest">ParameterSetUsedRequest</a> — ParameterSetUsedRequest : Used by a remote to update the used flag for a parameter on the primary.</li><li><a href="./ParameterSetValueRequest">ParameterSetValueRequest</a> — ParameterSetValueRequest : Used by a remote or primary to update the value for a parameter at the other end.</li><li><a href="./ParameterSetValueResponse">ParameterSetValueResponse</a> — ParameterSetValueResponse : Response to a set value request by either primary or secondary.</li><li><a href="./ParameterUpdate">ParameterUpdate</a> — This message is used to notify the system about one or more parameter changes.</li><li><a href="./Ping">Ping</a></li><li><a href="./PositionControllerLandingStatus">PositionControllerLandingStatus</a></li><li><a href="./PositionControllerStatus">PositionControllerStatus</a></li><li><a href="./PositionSetpoint">PositionSetpoint</a> — this file is only used in the position_setpoint triple as a dependency.</li><li><a href="./PositionSetpointTriplet">PositionSetpointTriplet</a> — Global position setpoint triplet in WGS84 coordinates. This are the three next waypoints (or just the next two or one).</li><li><a href="./PowerButtonState">PowerButtonState</a> — power button state notification message.</li><li><a href="./PowerMonitor">PowerMonitor</a> — power monitor message.</li><li><a href="./PpsCapture">PpsCapture</a></li><li><a href="./PrecLandStatus">PrecLandStatus</a> — Precision-landing runtime status: a single state captures both whether precision landing is active and which phase it is in.</li><li><a href="./PurePursuitStatus">PurePursuitStatus</a> — Pure pursuit status.</li><li><a href="./PwmInput">PwmInput</a></li><li><a href="./Px4ioStatus">Px4ioStatus</a></li><li><a href="./QshellReq">QshellReq</a></li><li><a href="./QshellRetval">QshellRetval</a></li><li><a href="./RadioStatus">RadioStatus</a></li><li><a href="./RangingBeacon">RangingBeacon</a> — Ranging beacon measurement data (e.g. LoRa, UWB).</li><li><a href="./RateCtrlStatus">RateCtrlStatus</a></li><li><a href="./RcChannels">RcChannels</a></li><li><a href="./RcParameterMap">RcParameterMap</a></li><li><a href="./RoverAttitudeSetpoint">RoverAttitudeSetpoint</a> — Rover Attitude Setpoint.</li><li><a href="./RoverAttitudeStatus">RoverAttitudeStatus</a> — Rover Attitude Status.</li><li><a href="./RoverPositionSetpoint">RoverPositionSetpoint</a> — Rover Position Setpoint.</li><li><a href="./RoverRateSetpoint">RoverRateSetpoint</a> — Rover Rate setpoint.</li><li><a href="./RoverRateStatus">RoverRateStatus</a> — Rover Rate Status.</li><li><a href="./RoverSpeedSetpoint">RoverSpeedSetpoint</a> — Rover Speed Setpoint.</li><li><a href="./RoverSpeedStatus">RoverSpeedStatus</a> — Rover Velocity Status.</li><li><a href="./RoverSteeringSetpoint">RoverSteeringSetpoint</a> — Rover Steering setpoint.</li><li><a href="./RoverThrottleSetpoint">RoverThrottleSetpoint</a> — Rover Throttle setpoint.</li><li><a href="./Rpm">Rpm</a></li><li><a href="./RtcmData">RtcmData</a> — RTCM3 data exchanged with GNSS receivers.</li><li><a href="./RtlStatus">RtlStatus</a></li><li><a href="./RtlTimeEstimate">RtlTimeEstimate</a></li><li><a href="./SatelliteInfo">SatelliteInfo</a></li><li><a href="./SensorAccel">SensorAccel</a></li><li><a href="./SensorAccelFifo">SensorAccelFifo</a></li><li><a href="./SensorAirflow">SensorAirflow</a></li><li><a href="./SensorBaro">SensorBaro</a> — Barometer sensor.</li><li><a href="./SensorCombined">SensorCombined</a> — Sensor readings in SI-unit form. These fields are scaled and offset-compensated where possible and do not. change with board revisions and sensor updates.</li><li><a href="./SensorCorrection">SensorCorrection</a> — Sensor corrections in SI-unit form for the voted sensor.</li><li><a href="./SensorGnssRelative">SensorGnssRelative</a> — GNSS relative positioning information in NED frame. The NED frame is defined as the local topological system at the reference station.</li><li><a href="./SensorGnssStatus">SensorGnssStatus</a> — Gnss quality indicators.</li><li><a href="./SensorGps">SensorGps</a> — GPS position in WGS84 coordinates. the field &#39;timestamp&#39; is for the position &amp; velocity (microseconds).</li><li><a href="./SensorGyro">SensorGyro</a></li><li><a href="./SensorGyroFft">SensorGyroFft</a></li><li><a href="./SensorGyroFifo">SensorGyroFifo</a></li><li><a href="./SensorHygrometer">SensorHygrometer</a></li><li><a href="./SensorMag">SensorMag</a></li><li><a href="./SensorOpticalFlow">SensorOpticalFlow</a></li><li><a href="./SensorPreflightMag">SensorPreflightMag</a> — Pre-flight sensor check metrics. The topic will not be updated when the vehicle is armed.</li><li><a href="./SensorSelection">SensorSelection</a> — Sensor ID&#39;s for the voted sensors output on the sensor_combined topic. Will be updated on startup of the sensor module and when sensor selection changes.</li><li><a href="./SensorTemp">SensorTemp</a></li><li><a href="./SensorUwb">SensorUwb</a> — UWB distance contains the distance information measured by an ultra-wideband positioning system,. such as Pozyx or NXP Rddrone.</li><li><a href="./SensorsStatus">SensorsStatus</a> — Sensor check metrics. This will be zero for a sensor that&#39;s primary or unpopulated.</li><li><a href="./SensorsStatusImu">SensorsStatusImu</a> — Sensor check metrics. This will be zero for a sensor that&#39;s primary or unpopulated.</li><li><a href="./SystemPower">SystemPower</a></li><li><a href="./TakeoffStatus">TakeoffStatus</a> — Status of the takeoff state machine currently just available for multicopters.</li><li><a href="./TargetGnss">TargetGnss</a> — Landing target GNSS position in WGS84 coordinates, and optional NED velocity, from a target-mounted receiver.</li><li><a href="./TaskStackInfo">TaskStackInfo</a> — stack information for a single running process.</li><li><a href="./TecsStatus">TecsStatus</a></li><li><a href="./TelemetryStatus">TelemetryStatus</a></li><li><a href="./TiltrotorExtraControls">TiltrotorExtraControls</a></li><li><a href="./TimesyncStatus">TimesyncStatus</a></li><li><a href="./TrajectorySetpoint6dof">TrajectorySetpoint6dof</a> — Trajectory setpoint in NED frame. Input to position controller.</li><li><a href="./TransponderReport">TransponderReport</a> — Transponder report.</li><li><a href="./TuneControl">TuneControl</a> — This message is used to control the tunes, when the tune_id is set to CUSTOM. then the frequency, duration are used otherwise those values are ignored.</li><li><a href="./UavcanFirmwareUpdate">UavcanFirmwareUpdate</a></li><li><a href="./UavcanParameterRequest">UavcanParameterRequest</a> — UAVCAN-MAVLink parameter bridge request type.</li><li><a href="./UavcanParameterValue">UavcanParameterValue</a> — UAVCAN-MAVLink parameter bridge response type.</li><li><a href="./UlogStream">UlogStream</a> — Message to stream ULog data from the logger. Corresponds to the LOGGING_DATA. mavlink message.</li><li><a href="./UlogStreamAck">UlogStreamAck</a> — Ack a previously sent ulog_stream message that had. the NEED_ACK flag set.</li><li><a href="./VehicleAcceleration">VehicleAcceleration</a></li><li><a href="./VehicleAirData">VehicleAirData</a> — Vehicle air data.</li><li><a href="./VehicleConstraints">VehicleConstraints</a> — Local setpoint constraints in NED frame. setting something to NaN means that no limit is provided.</li><li><a href="./VehicleControlMode">VehicleControlMode</a> — Defines which controllers should run.</li><li><a href="./VehicleImu">VehicleImu</a> — IMU readings in SI-unit form.</li><li><a href="./VehicleImuStatus">VehicleImuStatus</a></li><li><a href="./VehicleLocalPositionSetpoint">VehicleLocalPositionSetpoint</a> — Local position setpoint in NED frame. Telemetry of PID position controller to monitor tracking. NaN means the state was not controlled.</li><li><a href="./VehicleMagnetometer">VehicleMagnetometer</a></li><li><a href="./VehicleOpticalFlow">VehicleOpticalFlow</a> — Optical flow in XYZ body frame in SI units.</li><li><a href="./VehicleOpticalFlowVel">VehicleOpticalFlowVel</a></li><li><a href="./VehicleRoi">VehicleRoi</a> — Vehicle Region Of Interest (ROI).</li><li><a href="./VehicleThrustSetpoint">VehicleThrustSetpoint</a> — Vehicle thrust setpoint.</li><li><a href="./VehicleTorqueSetpoint">VehicleTorqueSetpoint</a></li><li><a href="./VelocityLimits">VelocityLimits</a> — Velocity and yaw rate limits for a multicopter position slow mode only.</li><li><a href="./VteAidSource1d">VteAidSource1d</a> — Vision Target Estimator 1D fusion aid-source diagnostics (e.g. yaw).</li><li><a href="./VteAidSource3d">VteAidSource3d</a> — Vision Target Estimator 3D fusion aid-source diagnostics, one fusion_status per NED axis.</li><li><a href="./VteBiasInitStatus">VteBiasInitStatus</a> — Diagnostics for the initial GNSS/vision bias averaging phase in the Vision Target Estimator.</li><li><a href="./VteInput">VteInput</a> — Vehicle inputs fed into the Vision Target Estimator position prediction step, logged for tuning.</li><li><a href="./VteOrientation">VteOrientation</a> — Vision Target Estimator orientation state, exposing the full yaw filter output with covariances for logging and tuning.</li><li><a href="./VtePosition">VtePosition</a> — Vision Target Estimator position state, exposing the full per-axis Kalman filter state with covariances for logging and tuning.</li><li><a href="./Vtx">Vtx</a></li><li><a href="./WheelEncoders">WheelEncoders</a></li><li><a href="./YawEstimatorStatus">YawEstimatorStatus</a></li></ul>',12)])])}const m=t(r,[["render",l]]);export{d as __pageData,m as default};
